#include <algorithm>
#include <cstdint>
#include <optional>
#include <string>
#include <vector>

using DWORD = std::uint32_t;
constexpr DWORD ERROR_INSUFFICIENT_BUFFER = 122;
constexpr DWORD ERROR_MOD_NOT_FOUND = 126;
inline std::wstring g_modulePath{ L"C:\\Program Files\\Xenon\\xenon.exe" };
inline bool g_fail{ false };
inline DWORD g_lastError{ 0 };
inline int g_calls{ 0 };

DWORD FakeGetModuleFileName(wchar_t* buffer, DWORD size)
{
    ++g_calls;
    if (g_fail) { g_lastError = ERROR_MOD_NOT_FOUND; return 0; }
    if (size == 0) { g_lastError = ERROR_INSUFFICIENT_BUFFER; return 0; }
    const auto length{ static_cast<DWORD>(g_modulePath.size()) };
    if (length + 1 > size)
    {
        g_modulePath.copy(buffer, size - 1);
        buffer[size - 1] = L'\0';
        g_lastError = ERROR_INSUFFICIENT_BUFFER;
        return size;
    }
    g_modulePath.copy(buffer, length);
    buffer[length] = L'\0';
    g_lastError = 0;
    return length;
}

std::optional<std::wstring> modulePath()
{
    constexpr DWORD largest{ 32768 };
    DWORD size{ 260 };
    for (;;)
    {
        std::vector<wchar_t> buffer(size);
        const DWORD n{ FakeGetModuleFileName(buffer.data(), size) };
        if (n == 0) return std::nullopt;
        if (n < size) return std::wstring(buffer.data(), n);
        if (size == largest) return std::nullopt;
        size = std::min(size * 2, largest);
    }
}

unitTests:
void usePath(std::size_t length) {
    g_modulePath = L"C:\\";
    while (g_modulePath.size() < length) g_modulePath += static_cast<wchar_t>(L'a' + g_modulePath.size() % 26);
    g_fail = false;
    g_calls = 0;
}
TEST("a short path in one call") {
    usePath(30);
    const auto p{ modulePath() };
    CHECK(p.has_value() && *p == g_modulePath);
    CHECK_EQ(g_calls, 1);
}
TEST("exactly filling the first buffer") {
    usePath(259);
    const auto p{ modulePath() };
    CHECK(p.has_value() && *p == g_modulePath);
    CHECK_EQ(g_calls, 1);
}
TEST("one character too long") {
    usePath(260);
    const auto p{ modulePath() };
    CHECK(p.has_value() && *p == g_modulePath);
    CHECK_EQ(g_calls, 2);
}
TEST("growing several times") {
    usePath(1000);
    const auto p{ modulePath() };
    CHECK(p.has_value() && p->size() == 1000 && *p == g_modulePath);
    CHECK_EQ(g_calls, 3);
    usePath(32767);
    const auto longest{ modulePath() };
    CHECK(longest.has_value() && longest->size() == 32767);
}
TEST("failures") {
    usePath(20);
    g_fail = true;
    CHECK(!modulePath().has_value());
    usePath(40000);
    CHECK(!modulePath().has_value());
    CHECK_EQ(g_calls, 8);
}

